"""Check dependency reachability for the isolated commuting-frontier prototype."""
import json
from pathlib import Path
import random
import signal
from flagquantum.core.ir import Instruction
from flagquantum.compiler.optimization.commutation import commute
namespace = {}
source = Path('/private/tmp/fq-commuting-frontier-guarded-20261123.py').read_text().split('roadmap_path =',1)[0]
exec(compile(source, '<frontier-prototype-setup>', 'exec'), namespace)
original, candidate = namespace['original'], namespace['candidate']
signal.alarm(90)

def reachable(successors):
    result = [set() for _ in successors]
    for i in range(len(successors)-1,-1,-1):
        for j in successors[i]:
            assert j > i
            result[i].add(j)
            result[i].update(result[j])
    return result

rng = random.Random(241123)
rows = []
for length in (1, 10, 31, 32, 33, 64, 100):
    for seed in range(16):
        program = []
        for _ in range(length):
            name = rng.choice(('rx','rz','cz','rzz','cx','barrier','measure'))
            wires = tuple(rng.sample(range(6),2 if name in ('cz','rzz','cx') else 1))
            params = {'theta':rng.uniform(-3,3)} if name in ('rx','rz','rzz') else {}
            metadata = {'classical_bit':rng.randrange(3), 'is_dynamic':True} if name == 'measure' else ({'is_dynamic':True} if name == 'barrier' else {})
            if name not in ('measure','barrier') and rng.random() < .2:
                metadata['conditions'] = ((rng.randrange(3),1),)
            program.append(Instruction(name,wires,params=params,metadata=metadata))
        program = tuple(program)
        graph, pending = candidate(program)
        reach = reachable(graph)
        computed = [0] * len(program)
        for nexts in graph:
            for j in nexts: computed[j] += 1
        assert computed == list(pending)
        for i,a in enumerate(program):
            for j in range(i+1,len(program)):
                b = program[j]
                if set(a.wires) & set(b.wires) and not commute(a,b):
                    assert j in reach[i], (length,seed,i,j)
        last_writer = {}
        readers = {}
        accesses = namespace['sabre']._classical_accesses
        for j,instruction in enumerate(program):
            written, read = accesses(instruction)
            for bit in read:
                if bit in last_writer: assert j in reach[last_writer[bit]]
            if written is not None:
                if written in last_writer: assert j in reach[last_writer[written]]
                for i in readers.pop(written,[]): assert j in reach[i]
                last_writer[written] = j
            for bit in read: readers.setdefault(bit,[]).append(j)
        rows.append({'length':length,'seed':seed,'edges':sum(map(len,graph)),'max_pending':max(pending,default=0)})
# Force a single commuting group across the exact 32-member boundary.
for length in (31,32,33,64,65,1000):
    program = tuple(Instruction('cz',(0,1)) for _ in range(length))
    graph,pending = candidate(program)
    reach = reachable(graph)
    for i in range(length):
        for j in range((i//32+1)*32,length): assert j in reach[i]
    assert sum(map(len,graph)) <= 32*2*length
    rows.append({'commuting_length':length,'edges':sum(map(len,graph)),'max_pending':max(pending,default=0)})
for metadata in ({'routing_phase':'forward'}, {'is_channel':True}, {'is_dynamic':True}, {'conditions':((0,1),)}):
    program = (Instruction('cz',(0,1)), Instruction('cz',(0,1),metadata=metadata), Instruction('cz',(0,1)))
    graph,pending = candidate(program)
    reach = reachable(graph)
    assert 1 in reach[0] and 2 in reach[1], metadata
    rows.append({'protected_metadata':metadata,'edges':sum(map(len,graph))})
output = {'scope':'Prototype graph invariants only; not production or performance acceptance','cases':rows,'driver_source':Path(__file__).read_text()}
Path('/private/tmp/fq-commuting-frontier-guarded-graph-20261123.json').write_text(json.dumps(output,indent=2)+'\n')
print(json.dumps({'cases':len(rows),'status':'passed'}))

