"""Observe both arms in fresh bounded workers without timing qualification."""
import json,os,signal,subprocess,time
from pathlib import Path
source=json.loads(Path('/private/tmp/fq-commuting-frontier-resources-20261123.json').read_text())
assert source['complete']
selected=[r for r in source['rows'] if r['instance'].startswith('EXT-') or r['workflow']=='flagquantum-target-artifact']
worker=Path('/private/tmp/fq-commuting-frontier-rss-worker-20261123.py')
report={'scope':'Shared macOS fresh-process peak RSS observations, not an enforced memory cap or qualified host result','worker_source':worker.read_text(),'driver_source':Path(__file__).read_text(),'per_worker_wall_seconds':20,'memory_cgroup_enforced':False,'complete':False,'rows':[]}
output=Path('/private/tmp/fq-commuting-frontier-rss-20261123.json')
for row in selected:
 for repeat in range(3):
  for arm in (('baseline','candidate') if repeat%2==0 else ('candidate','baseline')):
   request={'arm':arm,'workflow':row['workflow'],'fixture':row['fixture']}
   process=subprocess.Popen(['/Users/baai/Documents/liuwei/sdkbench/.venv/bin/python',str(worker)],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True)
   started=time.monotonic()
   try:
    stdout,stderr=process.communicate(json.dumps(request),timeout=20)
    if process.returncode:
     outcome={'status':'error','exit_code':process.returncode,'stdout':stdout,'stderr':stderr}
    else:
     outcome=json.loads(stdout);outcome['status']='accepted'
     assert outcome['output_sha256']==row['summaries'][arm]['output_sha256'],(row['instance'],arm)
   except subprocess.TimeoutExpired:
    os.killpg(process.pid,signal.SIGTERM)
    try:stdout,stderr=process.communicate(timeout=5)
    except subprocess.TimeoutExpired:
     os.killpg(process.pid,signal.SIGKILL);stdout,stderr=process.communicate(timeout=5)
    outcome={'status':'timeout','stdout':stdout,'stderr':stderr,'exit_code':process.returncode}
   report['rows'].append({'instance':row['instance'],'workflow':row['workflow'],'repeat':repeat,'arm':arm,'outcome':outcome,'worker_wall_seconds':time.monotonic()-started})
   output.write_text(json.dumps(report,indent=2)+'\n')
 print(json.dumps({'instance':row['instance'],'completed_workers':len(report['rows'])}),flush=True)
report['complete']=True
output.write_text(json.dumps(report,indent=2)+'\n')
